node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import {readFileSync,existsSync} from 'node:fs';
import path from 'node:path';
const files = ['docs/BOARD.md','docs/VERIFICATION.md'];
function slug(text) {
 return text.trim().toLowerCase().replace(/<[^>]*>/gu,'').replace(/[\x60*_~]/gu,'').replace(/[.,:;!?()[\]{}'"\\/|<>@#$%^&+=]/gu,'').replace(/\s/gu,'-');
}
function anchors(text) {
 const result=new Set(); const seen=new Map();
 for(const line of text.split(/\r?\n/u)) {
  const m=/^#{1,6}\s+(.+?)\s*$/u.exec(line); if(!m) continue;
  const base=slug(m[1]); const ordinal=seen.get(base)??0; seen.set(base,ordinal+1);
  result.add(ordinal===0?base:base+'-'+ordinal);
 }
 return result;
}
let localLinks=0;
const problems=[];
for(const file of files) {
 const text=readFileSync(file,'utf8');
 for(const match of text.matchAll(/\]\(([^)\s#]*)(#[^)\s]+)?\)/gu)) {
  const [,reference,fragment]=match;
  if(/^(?:https?:|mailto:)/u.test(reference)) continue;
  const target=reference?path.resolve(path.dirname(file),reference):path.resolve(file);
  localLinks++;
  if(!existsSync(target)) {problems.push(file+' -> '+reference+': missing'); continue;}
  if(fragment && target.endsWith('.md') && !anchors(readFileSync(target,'utf8')).has(fragment.slice(1))) problems.push(file+' -> '+reference+fragment+': missing anchor');
 }
}
assert.ok(localLinks>0);
assert.deepEqual(problems,[]);
console.log(JSON.stringify({files,localLinks,problems,status:'PASS',scope:'Supplementary changed-file link resolution, including untracked documents. Does not replace the repository checker.'},null,2));
